import fs from 'node:fs';import path from 'node:path';import {pathToFileURL} from 'node:url';import assert from 'node:assert/strict';export {assert};
export const E=path.dirname(new URL(import.meta.url).pathname);
export const info=JSON.parse(fs.readFileSync(process.env.RUNTIME_INFO,'utf8'));
export const {chromium}=await import(pathToFileURL(info.tree+'/modules/ui-web/node_modules/playwright-core/index.mjs'));
export const sleep=ms=>new Promise(r=>setTimeout(r,ms));
export async function eventually(fn,ms=30000){let e;const end=Date.now()+ms;while(Date.now()<end){try{return await fn()}catch(x){e=x}await sleep(200)}throw e}
export function surfaceUrl(target,state={}){const s=new URLSearchParams();for(const[k,v]of Object.entries(state))for(const x of Array.isArray(v)?v:[v])s.append(k,x);return '#justsearch://surface/'+target+(s.size?'?'+s:'')}
export async function text(p,selector='jf-shell'){return p.locator(selector).first().evaluate(e=>{function t(n){if(n.nodeType===3)return n.textContent;if(n.nodeType===1&&['SCRIPT','STYLE'].includes(n.tagName))return '';return [...n.childNodes].map(t).join(' ')+(n.shadowRoot?t(n.shadowRoot):'')}return t(e)})}
export async function dismiss(p){const b=p.getByRole('button',{name:'Dismiss',exact:true});if(await b.isVisible())await b.click()}
export async function type(input,s){await input.click();await input.press('Control+A');await input.press('Backspace');await input.pressSequentially(s,{delay:1})}
export async function boot(p,state={},target='core.search-v3-surface'){if(process.env.BASELINE_DEVELOPER==='1'){await p.goto('http://127.0.0.1:'+info.port+'/?api_port='+info.enginePort);await p.locator('jf-unified-chat-view jf-composer textarea').waitFor({timeout:60000});await dismiss(p);await p.getByRole('button',{name:'Settings',exact:true}).click();await p.getByRole('button',{name:'Developer',exact:true}).click();await p.locator('jf-option-button-group button').filter({hasText:'Show everything'}).click();await p.keyboard.press('Escape');}await p.goto('http://127.0.0.1:'+info.port+'/?api_port='+info.enginePort+surfaceUrl(target,state),{waitUntil:'domcontentloaded'});await p.locator('[data-testid=sv3-composer-input],jf-unified-chat-view jf-composer textarea').first().waitFor({state:'visible',timeout:90000}); if(!await p.getByTestId('sv3-composer-input').isVisible()){await sleep(8000);} if(!await p.getByTestId('sv3-composer-input').isVisible()){assert.fail('Main opens old chat window for this address; Search v3 main-window predicate fails before');}await dismiss(p);await sleep(600)}
export async function run(name,fn,options={}){
 const originalName=name;let attempt=1;while(fs.existsSync(path.join(E,info.label,name)))name=originalName+'-attempt-'+(++attempt);const dir=path.join(E,info.label,name);fs.mkdirSync(dir,{recursive:true});const short=fs.mkdtempSync('/tmp/jsv-');const wire=[],errors=[],consoleLines=[],navigations=[];let ctx,p,result={name,commit:info.head};
 const env={...process.env,TMPDIR:short,HOME:short,XDG_CONFIG_HOME:short+'/config',XDG_CACHE_HOME:short+'/cache',CUDA_VISIBLE_DEVICES:'-1'};for(const k of Object.keys(env))if(k.startsWith('JUSTSEARCH_')||['JAVA_TOOL_OPTIONS','JDK_JAVA_OPTIONS','JAVA_OPTS','_JAVA_OPTIONS','DISPLAY','WAYLAND_DISPLAY','RUNTIME_TOKEN'].includes(k))delete env[k];
 try{ctx=await chromium.launchPersistentContext(short+'/p',{executablePath:'/home/elias/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome',headless:true,chromiumSandbox:false,args:['--disable-gpu','--no-sandbox'],env,viewport:options.viewport??{width:1600,height:1000}});p=ctx.pages()[0];p.setDefaultTimeout(15000);
 p.on('framenavigated',f=>{if(f===p.mainFrame())navigations.push({event:'framenavigated',url:f.url(),at:Date.now()})});p.on('domcontentloaded',()=>navigations.push({event:'domcontentloaded',url:p.url(),at:Date.now()}));p.on('pageerror',e=>errors.push(String(e)));p.on('console',m=>consoleLines.push(m.text()));
 p.on('request',r=>{if(new URL(r.url()).pathname.startsWith('/api/'))wire.push({at:Date.now(),method:r.method(),url:r.url(),body:r.postData()})});
 const snap=async n=>{fs.writeFileSync(dir+'/'+n+'.txt',await p.locator('body').ariaSnapshot());fs.writeFileSync(dir+'/'+n+'.json',JSON.stringify({url:p.url(),text:await text(p),storage:await p.evaluate(()=>({local:{...localStorage},session:{...sessionStorage}}))},null,2));await p.screenshot({path:dir+'/'+n+'.png'})};
 result.detail=await fn({p,ctx,wire,errors,consoleLines,dir,snap});result.status='pass';
 }catch(e){result.status='fail';result.error=e.stack;if(!ctx){result.status='unverified';fs.writeFileSync(process.env.RUNTIME_OUT+'/browser-startup-failure.json',JSON.stringify({error:e.stack,name},null,2));throw e}if(p){try{fs.writeFileSync(dir+'/failure.txt',await p.locator('body').ariaSnapshot());await p.screenshot({path:dir+'/failure.png'});fs.writeFileSync(dir+'/failure-ui.txt',await text(p))}catch{}}}
 finally{if(ctx)await ctx.close();fs.rmSync(short,{recursive:true,force:true});result.errors=errors;result.console=consoleLines;result.sandbox=false;result.profileRemoved=!fs.existsSync(short);fs.writeFileSync(dir+'/requests.json',JSON.stringify(wire,null,2));fs.writeFileSync(dir+'/navigations.json',JSON.stringify(navigations,null,2));fs.writeFileSync(dir+'/result.json',JSON.stringify(result,null,2));}
 console.log(name,result.status,result.error?.split('\n')[0]??'');return result;
}
export const work=wire=>wire.filter(x=>x.method!=='GET'&&/\/api\/chat\/(dispatch|agent\/(?!virtual-operations))/.test(x.url));

