 await p.getByTestId('sv3-composer-input').waitFor();await sleep(700);await snap('after-Back-proposal');
 const confirm=p.getByTestId('sv3-draft-review-confirm'),enabled=await confirm.count()>0&&await confirm.isEnabled();if(enabled)await confirm.click();
 await p.getByTestId('sv3-composer-input').press('Enter');await sleep(800);
