 await snap('after-review-and-Send');fs.writeFileSync(dir+'/observations.json',JSON.stringify({via,availability,confirmEnabled:enabled,requestedChosen:info.chosen,requests,composerText:await text(p,'jf-sv3-composer')},null,2));
 assert.equal(requests.length,0,'unchanged retired text is blocked even with the CPU model ready');assert.match(await text(p,'jf-sv3-composer'),/files and mode.*not kept/i);
}));if(rows.some(x=>x.status!=='pass'))process.exitCode=1;

