import fs from 'node:fs';
import {run,boot,text,work,sleep,assert,info,surfaceUrl,eventually} from './browser-lib.mjs';
let seededId;
const row=await run('D-T24-conversation-Back',async({p,wire,dir,snap})=>{
 await boot(p,{query:'Reply with exactly OK.',forceShapeId:'core.free-chat'});await sleep(1000);await p.getByTestId('sv3-composer-input').press('Enter');
 const request=await eventually(async()=>{const r=work(wire).find(x=>x.url.endsWith('/api/chat/dispatch'));assert.ok(r);return JSON.parse(r.body);});
 const cid=request.conversationId;seededId=cid;assert.ok(cid);const history=await eventually(async()=>{const r=await p.request.get('http://127.0.0.1:'+info.port+'/api/chat/conversations/'+cid+'/history');const h=await r.json();assert.ok(h.messages?.some(m=>m.role==='assistant'&&m.errorCode!=='INCOMPLETE_TURN'));return h;},180000);
 fs.writeFileSync(dir+'/genuine-seed.json',JSON.stringify({request,history},null,2));await snap('saved-conversation');
 const B='Incoming chosen question';await p.evaluate(h=>location.hash=h,surfaceUrl('core.search-v3-surface',{query:B,mode:'ask',docIds:[info.chosen]}));await sleep(700);await snap('incoming');
 const ids=await p.locator('jf-sv3-sidebar').evaluate(e=>e.groups.flatMap(g=>g.rows).map(r=>r.id));assert.ok(ids.includes(cid));await p.getByTestId('sv3-session-row-button').nth(ids.indexOf(cid)).click();await sleep(700);await snap('conversation');assert.ok(p.url().includes(cid));
 await p.goBack();await sleep(700);await snap('after-Back');
 const value=await p.getByTestId('sv3-composer-input').inputValue();const before=work(wire).length;
 await p.getByTestId('sv3-composer-input').press('Enter');await sleep(600);
 const preparation=await p.evaluate(()=>JSON.parse(sessionStorage.getItem('justsearch.draft.attachment.v1.search-v3.main')).payload);
 fs.writeFileSync(dir+'/observations.json',JSON.stringify({value,preparation,modelWork:work(wire),ui:await text(p)},null,2));
 assert.equal(work(wire).length,before,'Back never sends retired/retained hand-off automatically or as unnoticed all files');
 assert.ok(preparation.drafts.some(d=>d.text===B&&d.preparation?.scope?.paths?.includes(info.chosen)),'original proposal remains available for explicit review');
 assert.ok(value!==B||/review|not kept/i.test(await text(p)),'returned original text requires a visible choice');
});if(row.status!=='pass')process.exitCode=1;

// Added for the final guard-carry repair: a fresh window has not visited this saved row.
if(row.status==='pass') {
 const carried=await run('D-T24-carry-returned-text-to-conversation',async({p,wire,dir,snap})=>{
  const B='Unchanged task carried into a conversation';await boot(p,{query:B,mode:'ask',docIds:[info.chosen]});
  await p.getByRole('button',{name:'Manage indexed folders',exact:true}).click();await sleep(500);await p.goBack();await p.getByTestId('sv3-composer-input').waitFor();await sleep(600);
  const ids=await eventually(async()=>{const rows=await p.locator('jf-sv3-sidebar').evaluate(e=>e.groups.flatMap(g=>g.rows).map(r=>r.id));assert.ok(rows.includes(seededId));return rows;});
  await p.getByTestId('sv3-session-row-button').nth(ids.indexOf(seededId)).click();await sleep(700);await snap('carried-into-saved-conversation');
  assert.equal(await p.getByTestId('sv3-composer-input').inputValue(),B);assert.match(await text(p,'jf-sv3-composer'),/files and mode.*not kept/i);
  await p.getByTestId('sv3-composer-input').press('Enter');await sleep(600);assert.equal(work(wire).length,0);
  fs.writeFileSync(dir+'/observations.json',JSON.stringify({value:B,modelWork:work(wire),composerText:await text(p,'jf-sv3-composer'),savedConversation:seededId},null,2));
 });if(carried.status!=='pass')process.exitCode=1;
