// Adapted from verifier-4 matrix/scope-return.mjs for D-T24 (retire, visibly block).
import fs from 'node:fs';
import {run,boot,text,work,sleep,assert,info,surfaceUrl} from './browser-lib.mjs';
const routes=process.argv[2]? [process.argv[2]] : ['Library-Back','Library-rail','Forward-after-Back'];
const rows=[];
for(const via of routes) for(const count of [1,2,3]) rows.push(await run('D-T24-'+via+'-'+count,async({p,wire,dir,snap})=>{
 const B='Chosen B';await boot(p,{query:count===1?B:'Retained A',mode:'ask',docIds:[count===1?info.chosen:info.decoy]});
 if(count>1){await p.evaluate(h=>location.hash=h,surfaceUrl('core.search-v3-surface',{query:B,mode:'ask',docIds:[info.chosen]}));await sleep(600);}
 if(count>2){await p.evaluate(h=>location.hash=h,surfaceUrl('core.search-v3-surface',{query:'Capacity refused C',mode:'ask',docIds:[info.decoy]}));await sleep(600);assert.equal(await p.getByTestId('sv3-composer-input').inputValue(),B);assert.match(await text(p),/Only two draft preparations/);}
 await snap('prepared');await p.getByRole('button',{name:'Manage indexed folders',exact:true}).click();await sleep(500);
 if(via==='Library-rail') await p.getByRole('button',{name:'Search v3',exact:true}).click();
 else {await p.goBack();await p.getByTestId('sv3-composer-input').waitFor();await sleep(500);if(via==='Forward-after-Back'){await p.goForward();await sleep(500);assert.equal(await p.getByTestId('sv3-composer-input').count(),0);await p.goBack();}}
 await p.getByTestId('sv3-composer-input').waitFor();await sleep(600);await snap('returned');
 const composerText=await text(p,'jf-sv3-composer');
 const before=work(wire).length;await p.getByTestId('sv3-composer-input').press('Enter');await p.getByTestId('sv3-composer-send').click();await sleep(600);
 const observation={via,count,value:await p.getByTestId('sv3-composer-input').inputValue(),composerText,modelWork:work(wire),url:p.url(),storage:await p.evaluate(()=>JSON.parse(sessionStorage.getItem('justsearch.draft.attachment.v1.search-v3.main'))?.payload)};
 fs.writeFileSync(dir+'/observations.json',JSON.stringify(observation,null,2));
 assert.equal(observation.value,B);assert.match(composerText,/files and mode.*not kept/i);assert.match(composerText,/Sending is blocked/);assert.equal(work(wire).length,before);assert.equal(before,0);
}));
if(rows.some(x=>x.status!=='pass'))process.exitCode=1;
